package team7.model;

import java.time.LocalDateTime;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

/**
 * In-system alert generated by ComplianceScheduler (FR-11).
 * send() method is invoked by the scheduler service.
 */
@Entity
@Table(name = "alerts")
public class Alert {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "deadline_id", nullable = false)
    private Deadline deadline;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "recipient_id", nullable = false)
    private User recipient;

    @Column(nullable = false)
    private LocalDateTime sentAt;

    /** Must be 7, 1, or 0. */
    private int daysBeforeDue;

    private boolean read;

    public Alert() {}

    public Alert(Deadline deadline, User recipient, LocalDateTime sentAt, int daysBeforeDue) {
        this.deadline = deadline;
        this.recipient = recipient;
        this.sentAt = sentAt;
        this.daysBeforeDue = daysBeforeDue;
        this.read = false;
    }

    /** Persist this alert (called by ComplianceScheduler.checkDeadlines). */
    public void send() {
        // Persistence is handled by the repository; this method marks intent.
        this.read = false;
    }

    public Long getId() { return id; }
    public Deadline getDeadline() { return deadline; }
    public void setDeadline(Deadline deadline) { this.deadline = deadline; }
    public User getRecipient() { return recipient; }
    public void setRecipient(User recipient) { this.recipient = recipient; }
    public LocalDateTime getSentAt() { return sentAt; }
    public void setSentAt(LocalDateTime sentAt) { this.sentAt = sentAt; }
    public int getDaysBeforeDue() { return daysBeforeDue; }
    public void setDaysBeforeDue(int daysBeforeDue) { this.daysBeforeDue = daysBeforeDue; }
    public boolean isRead() { return read; }
    public void setRead(boolean read) { this.read = read; }
}
